      "customHtml": "<div class=\"overflow-x-auto my-6\">\n<table class=\"w-full text-left border-collapse\">\n<thead>\n<tr class=\"border-b border-outline\">\n<th class=\"py-2 pr-4\">المعطى</th>\n<th class=\"py-2 pr-4\">المطلوب</th>\n<th class=\"py-2 pr-4\">الصيغة</th>\n<th class=\"py-2\">متى تستخدمها</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"border-b border-outline/50\">\n<td class=\"py-2 pr-4\">الوتر c، والزاوية A</td>\n<td class=\"py-2 pr-4\">المقابل a</td>\n<td class=\"py-2 pr-4\">a = c x sin(A)</td>\n<td class=\"py-2\">طول القطر معلوم</td>\n</tr>\n<tr class=\"border-b border-outline/50\">\n<td class=\"py-2 pr-4\">الوتر c، والزاوية A</td>\n<td class=\"py-2 pr-4\">المجاور b</td>\n<td class=\"py-2 pr-4\">b = c x cos(A)</td>\n<td class=\"py-2\">طول القطر معلوم</td>\n</tr>\n<tr>\n<td class=\"py-2 pr-4\">المجاور b، والزاوية A</td>\n<td class=\"py-2 pr-4\">المقابل a</td>\n<td class=\"py-2 pr-4\">a = b x tan(A)</td>\n<td class=\"py-2\">مسافة القاعدة وحدها معلومة</td>\n</tr>\n</tbody>\n</table>\n</div>"
