      "customHtml": "<div class=\"overflow-x-auto my-6\">\n<table class=\"w-full text-left border-collapse\">\n<thead>\n<tr class=\"border-b border-outline\">\n<th class=\"py-2 pr-4\">Известно</th>\n<th class=\"py-2 pr-4\">Търсим</th>\n<th class=\"py-2 pr-4\">Формула</th>\n<th class=\"py-2\">Кога да го използвате</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"border-b border-outline/50\">\n<td class=\"py-2 pr-4\">Хипотенуза c, ъгъл A</td>\n<td class=\"py-2 pr-4\">Срещулежаща a</td>\n<td class=\"py-2 pr-4\">a = c x sin(A)</td>\n<td class=\"py-2\">Известна е диагоналната дължина</td>\n</tr>\n<tr class=\"border-b border-outline/50\">\n<td class=\"py-2 pr-4\">Хипотенуза c, ъгъл A</td>\n<td class=\"py-2 pr-4\">Прилежаща b</td>\n<td class=\"py-2 pr-4\">b = c x cos(A)</td>\n<td class=\"py-2\">Известна е диагоналната дължина</td>\n</tr>\n<tr>\n<td class=\"py-2 pr-4\">Прилежаща b, ъгъл A</td>\n<td class=\"py-2 pr-4\">Срещулежаща a</td>\n<td class=\"py-2 pr-4\">a = b x tan(A)</td>\n<td class=\"py-2\">Известно е само разстоянието на основата</td>\n</tr>\n</tbody>\n</table>\n</div>"
