      "customHtml": "<div class=\"overflow-x-auto my-6\">\n<table class=\"w-full text-left border-collapse\">\n<thead>\n<tr class=\"border-b border-outline\">\n<th class=\"py-2 pr-4\">Känt</th>\n<th class=\"py-2 pr-4\">Sök</th>\n<th class=\"py-2 pr-4\">Formel</th>\n<th class=\"py-2\">När du använder den</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"border-b border-outline/50\">\n<td class=\"py-2 pr-4\">Hypotenusa c, vinkel A</td>\n<td class=\"py-2 pr-4\">Motstående a</td>\n<td class=\"py-2 pr-4\">a = c x sin(A)</td>\n<td class=\"py-2\">Diagonallängd känd</td>\n</tr>\n<tr class=\"border-b border-outline/50\">\n<td class=\"py-2 pr-4\">Hypotenusa c, vinkel A</td>\n<td class=\"py-2 pr-4\">Närliggande b</td>\n<td class=\"py-2 pr-4\">b = c x cos(A)</td>\n<td class=\"py-2\">Diagonallängd känd</td>\n</tr>\n<tr>\n<td class=\"py-2 pr-4\">Närliggande b, vinkel A</td>\n<td class=\"py-2 pr-4\">Motstående a</td>\n<td class=\"py-2 pr-4\">a = b x tan(A)</td>\n<td class=\"py-2\">Endast basdistans känd</td>\n</tr>\n</tbody>\n</table>\n</div>"
